      "location": "Top-left title area, roughly (15, 45) to (860, 85)",
      "fact": "Bold black title reads 'Top Regions: Ad Spend vs Sales'. The plot is a scatter chart, not a time series."
    },
    {
      "location": "Plot area, x-axis from ~25 to ~75, y-axis from ~50 to ~180",
      "fact": "Five small blue circular markers are arranged in a clear upward-sloping line from lower-left to upper-right, indicating a strong positive relationship between the two axes."
    },
    {
      "location": "Upper-right marker, approx (1930, 375)",
      "fact": "The highest and rightmost point, labeled 'Region E', sits well above and to the right of all other points, making it the top performer on both axes."
    },
    {
      "location": "Lower-left marker, approx (445, 1410)",
      "fact": "The lowest and leftmost point, labeled 'Region A', is the smallest on both axes."
    },
    {
      "location": "Middle markers, approx (700,1350), (945,1210), (1150,1110)",
      "fact": "Three intermediate points labeled 'Region B', 'Region C', and 'Region D' lie between A and E in a near-linear progression."
    },
    {
      "location": "Each marker",
      "fact": "All five markers are the same blue color and similar size; the only differentiator is the text label above each point."
    }
  ],
  "printed_facts": [
    {
      "location": "X-axis label, bottom center ~ (1180, 1560)",
      "fact": "Axis title: 'Advertising Spend ($ thousands)'. Tick values: 25, 30, 35, 40, 45, 50, 55, 60, 65, 70, 75."
    },
    {
      "location": "Y-axis label, left rotated ~ (185, 850)",
      "fact": "Axis title: 'Sales ($ thousands)'. Tick values: 50, 60, 70, 80, 90, 100, 110, 120, 130, 140, 150, 160, 170, 180."
    },
    {
      "location": "Point labels (series = region name)",
      "fact": "Region A ≈ (30, 57); Region B ≈ (35, 65); Region C ≈ (42, 81); Region D ≈ (48, 92); Region E ≈ (70, 173). Values are read from axis gridlines, not printed as numbers."
    },
    {
      "location": "No legend, no gridlines, no reference lines, no error bars",
      "fact": "The chart contains only the five labeled scatter points and axis ticks; there are no trend lines, thresholds, or secondary series."
    }
  ],
  "public_definitions": [
    "Primary field 'Budget Recommendation' with three options: 'Hold and request full regional data analysis', 'Approve broader ad budget expansion', 'Defer recommendation until next budget cycle'.",
    "Companion selects: Recommendation area ('Regional ad budget'), Review record ('Top-region budget request'), Decision queue ('Regional budget review').",
    "Page instructions: 'Review the regional ad spend and sales dashboard, then submit the regional budget decision.' and 'Review dashboard evidence and submit an approval or evidence-review decision.'",
    "Completion label: 'Submit Form'."
